	internal class _Anon_GhidraFileFilter_1 : GhidraFileFilter
	{

			/* @Override */
			public bool accept(File file, GhidraFileChooserModel model) {
				if (file == null) {
					return false;
				}

				if (file.isDirectory()) {
					return true;
				}

				return file.getAbsolutePath().toLowerCase().endsWith("tool");
			}

